"""Verify requested embaas tensors against the reference used by the ONNX export."""
from pathlib import Path
import sys,json,torch
r=Path(sys.argv[1]);torch.set_num_threads(4);a=torch.load(r/'embaas/pytorch_model.bin',map_location='cpu',weights_only=True,mmap=True);b=torch.load(r/'reference/pytorch_model.bin',map_location='cpu',weights_only=True,mmap=True);extra=sorted(set(a)^set(b));different=[k for k in sorted(set(a)&set(b)) if a[k].shape!=b[k].shape or not torch.equal(a[k],b[k])];buf=b.get('embeddings.position_ids');position_ok=buf is not None and torch.equal(buf,torch.arange(buf.shape[1]).expand_as(buf));report={'requested_model':'embaas/sentence-transformers-multilingual-e5-large','reference_model':'intfloat/multilingual-e5-large','tensors_compared':len(set(a)&set(b)),'different_tensors':different,'additional_reference_buffers':extra,'shared_tensors_bit_identical':not different,'additional_reference_buffer_is_deterministic_position_ids':bool(position_ok),'learned_weights_match':not different and extra==['embeddings.position_ids'] and bool(position_ok)};assert report['learned_weights_match'],'Weights do not match';(r/'weight-verification.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
